#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <float.h>

#define MAX_OBSTACLES 100
#define MAX_PAIRS 100

typedef struct {
    double x, y, r;
} Obstacle;

typedef struct {
    double x, y;
} Point;

// Distance between two points
double dist(Point a, Point b) {
    return sqrt((a.x - b.x)*(a.x - b.x) + (a.y - b.y)*(a.y - b.y));
}

// Check if line segment from p1 to p2 intersects circle (center, radius)
// Returns the number of intersection points (0, 1, or 2)
int line_circle_intersection(Point p1, Point p2, Point center, double r, double *t1, double *t2) {
    double dx = p2.x - p1.x;
    double dy = p2.y - p1.y;
    double fx = p1.x - center.x;
    double fy = p1.y - center.y;

    double a = dx*dx + dy*dy;
    double b = 2*(fx*dx + fy*dy);
    double c = fx*fx + fy*fy - r*r;

    double discriminant = b*b - 4*a*c;
    if (discriminant < 0) return 0;

    double sqrt_disc = sqrt(discriminant);
    *t1 = (-b - sqrt_disc) / (2*a);
    *t2 = (-b + sqrt_disc) / (2*a);

    // Check if intersection points are within the segment [0,1]
    int count = 0;
    if (*t1 >= 0 && *t1 <= 1) count++;
    if (*t2 >= 0 && *t2 <= 1 && fabs(*t2 - *t1) > 1e-9) count++;

    return count;
}

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    Obstacle obstacles[MAX_OBSTACLES];
    for (int i = 0; i < N; i++) {
        scanf("%lf %lf %lf", &obstacles[i].x, &obstacles[i].y, &obstacles[i].r);
    }

    Point red[MAX_PAIRS], blue[MAX_PAIRS];
    for (int i = 0; i < M; i++) {
        scanf("%lf %lf", &red[i].x, &red[i].y);
    }
    for (int i = 0; i < M; i++) {
        scanf("%lf %lf", &blue[i].x, &blue[i].y);
    }

    double total_energy = 0.0;

    for (int pair = 0; pair < M; pair++) {
        Point r = red[pair];
        Point b = blue[pair];

        double min_energy = DBL_MAX;

        // Try direct shot (no obstacle penetration)
        double direct_energy = 0.0;
        for (int i = 0; i < N; i++) {
            double t1, t2;
            int hits = line_circle_intersection(r, b, 
                (Point){obstacles[i].x, obstacles[i].y}, obstacles[i].r, &t1, &t2);
            if (hits > 0) {
                direct_energy = DBL_MAX;
                break;
            }
        }
        if (direct_energy < DBL_MAX) {
            min_energy = 0.0;
        }

        // Try shooting through each obstacle
        for (int i = 0; i < N; i++) {
            double t1, t2;
            int hits = line_circle_intersection(r, b,
                (Point){obstacles[i].x, obstacles[i].y}, obstacles[i].r, &t1, &t2);
            if (hits > 0) {
                double energy = obstacles[i].r; // energy proportional to radius
                // Check if any other obstacles are also intersected
                for (int j = 0; j < N; j++) {
                    if (i == j) continue;
                    double u1, u2;
                    int hits2 = line_circle_intersection(r, b,
                        (Point){obstacles[j].x, obstacles[j].y}, obstacles[j].r, &u1, &u2);
                    if (hits2 > 0) {
                        energy += obstacles[j].r;
                    }
                }
                if (energy < min_energy) {
                    min_energy = energy;
                }
            }
        }

        if (min_energy == DBL_MAX) {
            // Should not happen according to problem, but handle gracefully
            min_energy = 0.0;
        }

        total_energy += min_energy;
    }

    printf("%.10f\n", total_energy);

    return 0;
}

