static const double EPS = 1e-10;

double dist3(Point a, Point b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    double dz = a.z - b.z;
    return sqrt(dx*dx + dy*dy + dz*dz);
}

/* Minimum distance from point C to segment AB */
double point_segment_distance(Point a, Point b, Point c) {
    double abx = b.x - a.x, aby = b.y - a.y, abz = b.z - a.z;
    double acx = c.x - a.x, acy = c.y - a.y, acz = c.z - a.z;
    double ab2 = abx*abx + aby*aby + abz*abz;
    if (ab2 < EPS) return dist3(a, c);

    double t = (abx*acx + aby*acy + abz*acz) / ab2;
    if (t < 0.0) t = 0.0;
    if (t > 1.0) t = 1.0;

    Point p;
    p.x = a.x + t * abx;
    p.y = a.y + t * aby;
    p.z = a.z + t * abz;
    return dist3(p, c);
}

int cmp_double(const void *pa, const void *pb) {
    double a = *(const double *)pa;
    double b = *(const double *)pb;
    if (a < b) return -1;
    if (a > b) return 1;
    return 0;
}

