        Sphere *s = (Sphere *)malloc(sizeof(Sphere) * n);
        if (!s) return 0;

        for (int i = 0; i < n; ++i) {
            scanf("%lf %lf %lf %lf %lf", &s[i].x, &s[i].y, &s[i].z, &s[i].r, &s[i].cost);
        }

        double answer = 0.0;

        for (int i = 0; i < n; ++i) {
            Point c = {s[i].x, s[i].y, s[i].z};
            double d = point_segment_distance(red, blue, c);
            if (d <= s[i].r + EPS) {
                answer += s[i].cost;
            }
        }

        /* Costs are integers in the original setting, but print safely */
        if (fabs(answer - round(answer)) < 1e-7) {
            printf("%.0f\n", round(answer));
        } else {
            printf("%.10f\n", answer);
        }

        free(s);
    }

    return 0;
}

