struct Point {
    double x, y;
    Point() : x(0), y(0) {}
    Point(double x, double y) : x(x), y(y) {}
};

struct Obstacle {
    Point center;
    double radius;
    double cost;
};

double distance(const Point& a, const Point& b) {
    return sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
}

bool lineIntersectsCircle(const Point& a, const Point& b, const Obstacle& obs) {
    double dx = b.x - a.x;
    double dy = b.y - a.y;
    double fx = a.x - obs.center.x;
    double fy = a.y - obs.center.y;

    double a_coeff = dx * dx + dy * dy;
    double b_coeff = 2 * (fx * dx + fy * dy);
    double c_coeff = fx * fx + fy * fy - obs.radius * obs.radius;

    double discriminant = b_coeff * b_coeff - 4 * a_coeff * c_coeff;

    if (discriminant < 0) return false;

    discriminant = sqrt(discriminant);
    double t1 = (-b_coeff - discriminant) / (2 * a_coeff);
    double t2 = (-b_coeff + discriminant) / (2 * a_coeff);

    // Check if intersection occurs between points a and b
    if (t1 >= 0 && t1 <= 1) return true;
    if (t2 >= 0 && t2 <= 1) return true;

    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    cin >> N;

    vector<Point> red(N), blue(N);
