    for (int i = 0; i < M; i++) {
        cin >> obstacles[i].center.x >> obstacles[i].center.y;
        cin >> obstacles[i].radius >> obstacles[i].cost;
    }

    double totalEnergy = 0;

    for (int i = 0; i < N; i++) {
        double minEnergy = 1e18;

        // Try direct path
        double directEnergy = 0;
        for (int j = 0; j < M; j++) {
            if (lineIntersectsCircle(red[i], blue[i], obstacles[j])) {
                directEnergy += obstacles[j].cost;
            }
        }
        minEnergy = min(minEnergy, directEnergy);

        // Try paths through obstacle centers
        for (int j = 0; j < M; j++) {
            // Red to obstacle center to blue
            double energy = 0;

            // Check red to obstacle center
            for (int k = 0; k < M; k++) {
                if (k == j) continue;
                if (lineIntersectsCircle(red[i], obstacles[j].center, obstacles[k])) {
                    energy += obstacles[k].cost;
                }
            }

            // Check obstacle center to blue
            for (int k = 0; k < M; k++) {
                if (k == j) continue;
                if (lineIntersectsCircle(obstacles[j].center, blue[i], obstacles[k])) {
                    energy += obstacles[k].cost;
                }
            }

            // Add cost of the obstacle we're passing through
            energy += obstacles[j].cost;

            minEnergy = min(minEnergy, energy);
        }

        totalEnergy += minEnergy;
    }

    cout << fixed << setprecision(1) << totalEnergy << endl;

    return 0;
}

