#include <bits/stdc++.h>
using namespace std;

struct Point {
    double x, y, z;
};

struct Sphere {
    Point c;
    double r, w;
};

static inline double sqr(double x) { return x * x; }

static inline Point operator-(const Point& a, const Point& b) {
    return {a.x - b.x, a.y - b.y, a.z - b.z};
}

static inline double dot(const Point& a, const Point& b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

static inline double norm2(const Point& a) {
    return dot(a, a);
}

// Whether segment AB touches/intersects sphere s
bool intersectsSegmentSphere(const Point& A, const Point& B, const Sphere& s) {
    Point AB{B.x - A.x, B.y - A.y, B.z - A.z};
    Point AC{s.c.x - A.x, s.c.y - A.y, s.c.z - A.z};

    double ab2 = norm2(AB);
    if (ab2 == 0.0) {
        return norm2(Point{A.x - s.c.x, A.y - s.c.y, A.z - s.c.z}) <= s.r * s.r + 1e-12;
    }

    double t = dot(AC, AB) / ab2;
    t = max(0.0, min(1.0, t));

    Point P{A.x + AB.x * t, A.y + AB.y * t, A.z + AB.z * t};
    double d2 = norm2(Point{P.x - s.c.x, P.y - s.c.y, P.z - s.c.z});
    return d2 <= s.r * s.r + 1e-12;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    while (cin >> n >> m) {
        vector<Sphere> obs(n);
        for (int i = 0; i < n; ++i) {
            cin >> obs[i].c.x >> obs[i].c.y >> obs[i].c.z >> obs[i].r >> obs[i].w;
        }

        double ans = 0.0;
        for (int i = 0; i < m; ++i) {
            Point R, B;
            cin >> R.x >> R.y >> R.z >> B.x >> B.y >> B.z;

            double cost = 0.0;
            for (int j = 0; j < n; ++j) {
                if (intersectsSegmentSphere(R, B, obs[j])) {
                    cost += obs[j].w;
                }
            }
            ans += cost;
        }

        cout << fixed << setprecision(10) << ans << '\n';
    }

    return 0;
}

