public class Solution {
    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }

        double distance(Point other) {
            double dx = this.x - other.x;
            double dy = this.y - other.y;
            return Math.sqrt(dx * dx + dy * dy);
        }
    }

    static class Obstacle {
        double x, y, r, cost;
        Obstacle(double x, double y, double r, double cost) {
            this.x = x;
            this.y = y;
            this.r = r;
            this.cost = cost;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;

        // Read number of obstacles
        line = br.readLine().trim();
        int N = Integer.parseInt(line);

        Obstacle[] obstacles = new Obstacle[N];
        for (int i = 0; i < N; i++) {
            String[] parts = br.readLine().trim().split(" ");
            double x = Double.parseDouble(parts[0]);
            double y = Double.parseDouble(parts[1]);
            double r = Double.parseDouble(parts[2]);
            double cost = Double.parseDouble(parts[3]);
            obstacles[i] = new Obstacle(x, y, r, cost);
        }

        // Read number of red-blue pairs
        line = br.readLine().trim();
        int M = Integer.parseInt(line);

        double totalEnergy = 0;

        for (int i = 0; i < M; i++) {
            String[] parts = br.readLine().trim().split(" ");
            double rx = Double.parseDouble(parts[0]);
            double ry = Double.parseDouble(parts[1]);
            double bx = Double.parseDouble(parts[2]);
            double by = Double.parseDouble(parts[3]);

            Point red = new Point(rx, ry);
            Point blue = new Point(bx, by);

            // For each pair, we need to find the minimum energy path
            // This can be solved by considering the obstacles as nodes in a graph
            // and using Dijkstra's algorithm

            totalEnergy += findMinEnergy(red, blue, obstacles);
        }

        System.out.printf("%.1f%n", totalEnergy);
    }

    static double findMinEnergy(Point start, Point end, Obstacle[] obstacles) {
        int n = obstacles.length;

        // Check if direct path is clear (no obstacles)
        boolean directClear = true;
        for (Obstacle obs : obstacles) {
            if (intersectsLine(start, end, obs)) {
                directClear = false;
                break;
            }
        }

        if (directClear) {
            return 0;
        }

        // Build graph: nodes are start, end, and tangency points on obstacles
        // For simplicity, we'll use the centers of obstacles and the start/end points
        // and find the minimum cost path using Dijkstra

        int totalNodes = n + 2; // obstacles + start + end
        List<List<double[]>> graph = new ArrayList<>();
        for (int i = 0; i < totalNodes; i++) {
            graph.add(new ArrayList<>());
        }

        // Calculate distances between all pairs
        Point[] points = new Point[totalNodes];
        points[0] = start;
        points[1] = end;
        for (int i = 0; i < n; i++) {
            points[i + 2] = new Point(obstacles[i].x, obstacles[i].y);
        }

        // Add edges
        for (int i = 0; i < totalNodes; i++) {
            for (int j = i + 1; j < totalNodes; j++) {
                double dist = points[i].distance(points[j]);

                // Check if this path intersects any obstacle
                double pathCost = 0;
                boolean blocked = false;

                for (int k = 0; k < n; k++) {
                    Obstacle obs = obstacles[k];
                    Point p1 = points[i];
                    Point p2 = points[j];

                    // Check if the line segment from p1 to p2 passes through this obstacle
                    if (intersectsLine(p1, p2, obs)) {
                        // Need to pay cost for this obstacle
                        pathCost += obs.cost;
                    }
                }

                graph.get(i).add(new double[]{j, dist + pathCost});
                graph.get(j).add(new double[]{i, dist + pathCost});
            }
        }

        // Dijkstra
        double[] dist = new double[totalNodes];
        Arrays.fill(dist, Double.MAX_VALUE);
        dist[0] = 0;

        PriorityQueue<double[]> pq = new PriorityQueue<>((a, b) -> Double.compare(a[1], b[1]));
        pq.offer(new double[]{0, 0});

        while (!pq.isEmpty()) {
            double[] curr = pq.poll();
            int u = (int)curr[0];
            double d = curr[1];

            if (d > dist[u]) continue;
            if (u == 1) break; // reached end

            for (double[] edge : graph.get(u)) {
                int v = (int)edge[0];
                double nd = d + edge[1];
                if (nd < dist[v]) {
                    dist[v] = nd;
                    pq.offer(new double[]{v, nd});
                }
            }
        }

        return dist[1];
    }

    static boolean intersectsLine(Point p1, Point p2, Obstacle obs) {
        // Check if line segment from p1 to p2 intersects the obstacle circle
        // Using vector projection method

        double dx = p2.x - p1.x;
        double dy = p2.y - p1.y;

        // Vector from p1 to obstacle center
        double fx = p1.x - obs.x;
        double fy = p1.y - obs.y;

        double a = dx * dx + dy * dy;
        double b = 2 * (fx * dx + fy * dy);
        double c = fx * fx + fy * fy - obs.r * obs.r;

        double discriminant = b * b - 4 * a * c;

        if (discriminant < 0) {
            return false; // No intersection
        }

        discriminant = Math.sqrt(discriminant);

        double t1 = (-b - discriminant) / (2 * a);
        double t2 = (-b + discriminant) / (2 * a);

        // Check if intersection occurs within the line segment
        return (t1 >= 0 && t1 <= 1) || (t2 >= 0 && t2 <= 1) || 
               (t1 < 0 && t2 > 1); // Line segment contains the circle
    }
}

