/*
We model each obstacle as a sphere with center (x,y,z), radius r, and cost c.
For each query: start point R and target point B.
A straight shot intersects some set of spheres. To guarantee reaching B from R,
we must pay the total cost of all spheres whose interiors/boundaries the segment RB touches.

But positions are not exact: each red/blue object is only known to lie inside its own sphere.
So for a red sphere A and blue sphere B, we need the minimum possible obstacle cost over
all choices of points p in A and q in B and the segment pq.

This is a minimum "barrier crossing" problem in 3D with spheres.
Key geometric/topological fact:
A segment from A to B can avoid all obstacles except those belonging to a separating cut
between A and B. In the dual graph of connected components of free space, this becomes a min-cut.
With spherical obstacles, we can solve it as a shortest path / min-cut on the intersection graph:

- Create a node for each obstacle sphere.
- Add source S connected to obstacle i with capacity c_i if obstacle i intersects red sphere.
- Add sink T connected from obstacle i with capacity c_i if obstacle i intersects blue sphere.
- Between obstacle i and j, if the spheres intersect/touch, add bidirectional infinite-capacity edge.

Then the minimum s-t cut equals the minimum total obstacle cost that must be "paid through".
Also, if red sphere intersects blue sphere, answer is 0.

This is the standard weighted separator on intersecting balls.

Input format inferred:
n m
then n lines: x y z r c   (obstacles)
then m lines: xr yr zr rr xb yb zb rb

If your judge uses a different but equivalent format, adapt parsing accordingly.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Sphere {
        long x, y, z, r, c;
        Sphere(long x, long y, long z, long r, long c) {
            this.x = x; this.y = y; this.z = z; this.r = r; this.c = c;
        }
    }

    static boolean intersect(long x1, long y1, long z1, long r1,
                             long x2, long y2, long z2, long r2) {
        long dx = x1 - x2;
        long dy = y1 - y2;
        long dz = z1 - z2;
        long sr = r1 + r2;
        return dx * dx + dy * dy + dz * dz <= sr * sr;
    }

    static class Edge {
        int to, rev;
        long cap;
        Edge(int to, int rev, long cap) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
        }
    }

    static class Dinic {
        int n;
        ArrayList<Edge>[] g;
        int[] level, it;

        @SuppressWarnings("unchecked")
        Dinic(int n) {
            this.n = n;
            g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
            level = new int[n];
            it = new int[n];
        }

        void addEdge(int fr, int to, long cap) {
            Edge f = new Edge(to, g[to].size(), cap);
            Edge r = new Edge(fr, g[fr].size(), 0);
            g[fr].add(f);
            g[to].add(r);
        }

        boolean bfs(int s, int t) {
            Arrays.fill(level, -1);
            ArrayDeque<Integer> q = new ArrayDeque<>();
            level[s] = 0;
            q.add(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (Edge e : g[v]) {
                    if (e.cap > 0 && level[e.to] < 0) {
                        level[e.to] = level[v] + 1;
                        q.add(e.to);
                    }
                }
            }
            return level[t] >= 0;
        }

        long dfs(int v, int t, long f) {
            if (v == t) return f;
            for (; it[v] < g[v].size(); it[v]++) {
                Edge e = g[v].get(it[v]);
                if (e.cap > 0 && level[v] + 1 == level[e.to]) {
                    long ret = dfs(e.to, t, Math.min(f, e.cap));
                    if (ret > 0) {
                        e.cap -= ret;
                        g[e.to].get(e.rev).cap += ret;
                        return ret;
                    }
                }
            }
            return 0;
        }

        long maxFlow(int s, int t) {
            long flow = 0;
            while (bfs(s, t)) {
                Arrays.fill(it, 0);
                long f;
                while ((f = dfs(s, t, Long.MAX_VALUE / 4)) > 0) {
                    flow += f;
                }
            }
            return flow;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n;
        int m;
        try {
            n = fs.nextInt();
            m = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        Sphere[] obs = new Sphere[n];
        for (int i = 0; i < n; i++) {
            long x = fs.nextLong();
            long y = fs.nextLong();
            long z = fs.nextLong();
            long r = fs.nextLong();
            long c = fs.nextLong();
            obs[i] = new Sphere(x, y, z, r, c);
        }

        // Precompute obstacle intersection graph
        boolean[][] touch = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            touch[i][i] = true;
            for (int j = i + 1; j < n; j++) {
                if (intersect(obs[i].x, obs[i].y, obs[i].z, obs[i].r,
                              obs[j].x, obs[j].y, obs[j].z, obs[j].r)) {
                    touch[i][j] = touch[j][i] = true;
                }
            }
        }

        StringBuilder out = new StringBuilder();
        long INF = Long.MAX_VALUE / 4;

        for (int qi = 0; qi < m; qi++) {
            long rx = fs.nextLong();
            long ry = fs.nextLong();
            long rz = fs.nextLong();
            long rr = fs.nextLong();

            long bx = fs.nextLong();
            long by = fs.nextLong();
            long bz = fs.nextLong();
            long br = fs.nextLong();

            if (intersect(rx, ry, rz, rr, bx, by, bz, br)) {
                out.append(0).append('\n');
                continue;
            }

            int S = n;
            int T = n + 1;
            Dinic dinic = new Dinic(n + 2);

            for (int i = 0; i < n; i++) {
                if (intersect(rx, ry, rz, rr, obs[i].x, obs[i].y, obs[i].z, obs[i].r)) {
                    dinic.addEdge(S, i, obs[i].c);
                }
                if (intersect(bx, by, bz, br, obs[i].x, obs[i].y, obs[i].z, obs[i].r)) {
                    dinic.addEdge(i, T, obs[i].c);
                }
            }

            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (touch[i][j]) {
                        dinic.addEdge(i, j, INF);
                        dinic.addEdge(j, i, INF);
                    }
                }
            }

            long ans = dinic.maxFlow(S, T);
            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }
